import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 19
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )
    records = list(reader)

    first_nonempty = None
    header_index = None
    for index, record in enumerate(records):
        labels = [value.strip() for value in record]
        if not any(labels):
            continue
        if first_nonempty is None:
            first_nonempty = index
        if (
            len(labels) == expected_width
            and all(any(char.isalpha() for char in label) for label in labels)
            and len({label.casefold() for label in labels}) == expected_width
        ):
            header_index = index
            break

    if header_index is None:
        header_index = first_nonempty
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [value.strip() for value in records[header_index]]
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    used_names = {name.casefold() for name in columns if name}
    for index in range(width):
        if index < len(columns) and columns[index]:
            continue
        base = "column_" + str(index + 1)
        name = base
        suffix = 2
        while name.casefold() in used_names:
            name = base + "_" + str(suffix)
            suffix += 1
        used_names.add(name.casefold())
        if index < len(columns):
            columns[index] = name
        else:
            columns.append(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
